def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 1.0))

    prev_bids = []
    stressed_bids = []
    max_opp_budget = 0.0
    danger_count = 0

    for opp in alive:
        obudget = float(opp.get('budget', 0.0))
        if obudget > max_opp_budget:
            max_opp_budget = obudget

        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            prev_bids.append(b)
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                stressed_bids.append(b)
            if b >= 80:
                danger_count += 1
        else:
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                danger_count += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    stressed_high = max(stressed_bids) if stressed_bids else highest_prev

    high_supply = supply >= 22
    low_supply = supply <= 17

    if hp <= 2 or no_water_days >= 2:
        base = max(92.0, stressed_high + 2.0, avg_prev + 8.0)
    elif hp <= 4 or no_water_days >= 1:
        base = max(72.0, min(96.0, stressed_high + 1.5), avg_prev + 4.0)
    else:
        if high_supply:
            base = 8.0 if danger_count >= 2 else 3.0
        elif low_supply:
            if highest_prev >= 100:
                base = 18.0
            elif highest_prev >= 80:
                base = 28.0
            else:
                base = max(36.0, avg_prev * 0.55)
        else:
            if highest_prev >= 100:
                base = 12.0
            elif highest_prev >= 80:
                base = 22.0
            else:
                base = max(26.0, avg_prev * 0.5)

    if day >= 8 and hp >= 5 and budget < max_opp_budget:
        base *= 0.85

    if day <= 2 and hp == 10 and high_supply:
        base = min(base, 10.0)

    cap = budget
    if hp >= 5:
        cap = min(cap, DAILY_SALARY * 1.05)
    elif hp >= 3:
        cap = min(cap, DAILY_SALARY * 1.35)

    bid = min(cap, base)
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 1))

    my_hp = int(my_status.get('hp', 0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace only
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate opponent pressure: use max surviving bids
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply-based aggressiveness: when supply is scarce, bidding competition is higher.
    # supply is between 15 and 25.
    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY != MIN_SUPPLY else 0.5
    scarcity = max(0.0, min(1.0, scarcity))

    # Target bid: just above the strongest yesterday bid if I'm healthy and supply is scarce.
    # If I'm low hp / already on no-water streak, bid harder.
    base = DAILY_SALARY * (0.55 + 0.35 * scarcity)  # ~49.5 to 90

    # If yesterday pressure was high, mirror it; otherwise, slightly undercut.
    if highest_prev_bid > 0:
        # If highest_prev_bid is in the ~survivor band, try to beat it marginally.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = highest_prev_bid + 2.0 * (0.5 + scarcity)
        else:
            target = max(base, highest_prev_bid + 1.0)
    else:
        target = base

    # Emergency escalation based on my hp/no_water_days
    if my_hp <= 2 or my_no_water_days >= 2:
        target = max(target, DAILY_SALARY * 0.9)
    elif my_hp <= 3:
        target = max(target, DAILY_SALARY * 0.75)

    # Budget cap
    bid = min(my_budget, target)

    # Avoid negative/NaN
    if bid != bid or bid < 0.0:
        bid = 0.0

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    target_bid = 105.0
    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        target_bid = max(100.0, avg_prev + 2.0)

    if my_status['hp'] <= 3:
        target_bid = max(target_bid, 115.0)

    return float(min(my_status['budget'], target_bid))
